package mihomo

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"net/http/httputil"
	"net/url"
	"os"
	"path/filepath"
	"runtime"
	"slices"
	"strconv"
	"sync/atomic"
	"testing"
	"time"
)

type websocketIntegrationTraffic struct {
	ObservedAt time.Time `json:"observed_at"`
	Traffic
}

// This opt-in test runs four sustained WebSocket subscriptions against a real,
// separate core. Every generated byte stays on loopback; there are no services,
// subscriptions, DNS listeners, TUN devices or host proxy changes.
func TestMihomoWebSocketIntegration(t *testing.T) {
	bin := integrationBinary(t)
	samples := 12
	if raw := os.Getenv("LAZYCLASH_WS_INTEGRATION_SAMPLES"); raw != "" {
		value, err := strconv.Atoi(raw)
		if err != nil || value < 12 || value > 120 {
			t.Fatal("LAZYCLASH_WS_INTEGRATION_SAMPLES must be between 12 and 120")
		}
		samples = value
	}
	ctx, cancel := context.WithTimeout(t.Context(), time.Duration(samples+20)*time.Second)
	defer cancel()
	version, err := BinaryVersion(ctx, bin)
	if err != nil {
		t.Fatal(err)
	}
	reserve := func() (net.Listener, int) {
		t.Helper()
		listener, err := net.Listen("tcp4", "127.0.0.1:0")
		if err != nil {
			t.Fatal("cannot reserve standalone core ports")
		}
		t.Cleanup(func() { _ = listener.Close() })
		return listener, listener.Addr().(*net.TCPAddr).Port
	}
	apiReservation, apiPort := reserve()
	mixedReservation, mixedPort := reserve()
	home := t.TempDir()
	controller := net.JoinHostPort("127.0.0.1", strconv.Itoa(apiPort))
	const secret = "synthetic-websocket-integration-secret"
	raw, err := Effective([]byte("mode: rule\nlog-level: silent\nproxies: []\nrules: ['MATCH,DIRECT']\n"), controller, secret, mixedPort)
	if err != nil {
		t.Fatal(err)
	}
	config := filepath.Join(home, "config.yaml")
	if err := os.WriteFile(config, raw, 0600); err != nil {
		t.Fatal("cannot write isolated core configuration")
	}
	_ = apiReservation.Close()
	_ = mixedReservation.Close()
	coreClient := Client{BaseURL: "http://" + controller, Secret: secret}
	startIntegrationCore(t, ctx, bin, home, config, coreClient)

	// Count handshakes at an actual HTTP reverse proxy. Reconnecting every
	// frame would still yield rates, but must fail this independent assertion.
	target, _ := url.Parse(coreClient.BaseURL)
	proxy := httputil.NewSingleHostReverseProxy(target)
	proxy.ErrorLog = nil
	proxy.ErrorHandler = func(w http.ResponseWriter, _ *http.Request, _ error) { w.WriteHeader(http.StatusBadGateway) }
	var handshakes [4]atomic.Int64
	paths := []string{"/traffic", "/memory", "/connections", "/logs"}
	proxyServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Upgrade") == "websocket" {
			for index, path := range paths {
				if r.URL.Path == path {
					handshakes[index].Add(1)
				}
			}
		}
		proxy.ServeHTTP(w, r)
	}))
	defer proxyServer.Close()
	client := Client{BaseURL: proxyServer.URL, Secret: secret}

	// A paced local HTTP response creates a stable, real connection and
	// actual nonzero transfer rates rather than replaying synthetic samples.
	local := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/octet-stream")
		chunk := make([]byte, 128<<10)
		sizes := [...]int{16 << 10, 48 << 10, 96 << 10, 32 << 10, 128 << 10, 64 << 10}
		count := 0
		ticker := time.NewTicker(100 * time.Millisecond)
		defer ticker.Stop()
		for {
			select {
			case <-r.Context().Done():
				return
			case <-ticker.C:
				if _, err := w.Write(chunk[:sizes[count/10%len(sizes)]]); err != nil {
					return
				}
				count++
				w.(http.Flusher).Flush()
			}
		}
	}))
	defer local.Close()
	mixedURL, _ := url.Parse(fmt.Sprintf("http://127.0.0.1:%d", mixedPort))
	trafficTransport := &http.Transport{Proxy: http.ProxyURL(mixedURL)}
	defer trafficTransport.CloseIdleConnections()
	trafficClient := &http.Client{Transport: trafficTransport}
	trafficCtx, stopTraffic := context.WithCancel(ctx)
	defer stopTraffic()
	request, _ := http.NewRequestWithContext(trafficCtx, http.MethodGet, local.URL, nil)
	response, err := trafficClient.Do(request)
	if err != nil {
		t.Fatal("cannot generate local HTTP proxy traffic")
	}
	defer response.Body.Close()
	trafficDone := make(chan struct{})
	go func() { _, _ = io.Copy(io.Discard, response.Body); close(trafficDone) }()

	streamCtx, stopStreams := context.WithCancel(ctx)
	defer stopStreams()
	type observation struct {
		source      string
		at          time.Time
		traffic     Traffic
		memory      uint64
		connections int
	}
	observations := make(chan observation, 256)
	errorsOut := make(chan error, 4)
	emit := func(value observation) {
		select {
		case observations <- value:
		case <-streamCtx.Done():
		}
	}
	started := time.Now()
	go func() {
		errorsOut <- client.StreamTraffic(streamCtx, func(value Traffic) {
			emit(observation{source: "traffic", at: time.Now(), traffic: value})
		})
	}()
	go func() {
		errorsOut <- client.StreamMemory(streamCtx, func(value uint64) {
			emit(observation{source: "memory", at: time.Now(), memory: value})
		})
	}()
	go func() {
		errorsOut <- client.StreamConnections(streamCtx, func(value ConnectionSnapshot) {
			emit(observation{source: "connections", at: time.Now(), connections: len(value.Connections)})
		})
	}()
	go func() {
		errorsOut <- client.StreamLogs(streamCtx, func(LogEntry) {
			emit(observation{source: "logs", at: time.Now()})
		})
	}()
	var points []websocketIntegrationTraffic
	var memoryFrames, connectionFrames, logFrames, maxConnections int
	var firstMemoryAt time.Time
	for len(points) < samples || memoryFrames < samples-2 || connectionFrames < samples {
		select {
		case <-ctx.Done():
			t.Fatalf("real WebSocket observation timed out: traffic=%d memory=%d connections=%d", len(points), memoryFrames, connectionFrames)
		case err := <-errorsOut:
			t.Fatalf("real WebSocket stream ended before cancellation: %v", err)
		case value := <-observations:
			switch value.source {
			case "traffic":
				points = append(points, websocketIntegrationTraffic{ObservedAt: value.at, Traffic: value.traffic})
			case "memory":
				memoryFrames++
				if firstMemoryAt.IsZero() {
					firstMemoryAt = value.at
				}
				if value.memory == 0 {
					t.Fatal("real memory subscription emitted an artificial zero")
				}
			case "connections":
				connectionFrames++
				maxConnections = max(maxConnections, value.connections)
			case "logs":
				logFrames++
			}
		}
	}
	stopStreams()
	for range 4 {
		select {
		case err := <-errorsOut:
			if !errors.Is(err, context.Canceled) {
				t.Fatalf("real WebSocket cancellation failed: %v", err)
			}
		case <-time.After(2 * time.Second):
			t.Fatal("real WebSocket connection did not close on cancellation")
		}
	}
	stopTraffic()
	select {
	case <-trafficDone:
	case <-time.After(2 * time.Second):
		t.Fatal("local traffic generator did not cancel")
	}
	counts := make(map[string]int64)
	for index, path := range paths {
		counts[path] = handshakes[index].Load()
		if counts[path] != 1 {
			t.Errorf("%s used %d WebSocket handshakes, want one sustained connection", path, counts[path])
		}
	}
	if logFrames != 0 {
		t.Errorf("silent core emitted %d log records", logFrames)
	}
	if maxConnections == 0 {
		t.Fatal("connection stream did not observe the real local HTTP transfer")
	}
	if firstMemoryAt.Sub(started) < 1500*time.Millisecond {
		t.Error("memory did not skip the new connection's first one-second frame")
	}
	intervals := make([]int64, 0, len(points)-1)
	var peak int64
	for index, point := range points {
		peak = max(peak, point.Down)
		if index > 0 {
			interval := point.ObservedAt.Sub(points[index-1].ObservedAt)
			intervals = append(intervals, interval.Nanoseconds())
			if interval < 500*time.Millisecond || interval > 1800*time.Millisecond {
				t.Errorf("real traffic interval %d = %s, want approximately one second", index, interval)
			}
		}
	}
	if peak == 0 || points[len(points)-1].DownTotal == 0 {
		t.Fatal("traffic subscription did not expose actual rate and cumulative bytes")
	}
	sorted := slices.Clone(intervals)
	slices.Sort(sorted)
	report := map[string]any{
		"version": version, "platform": runtime.GOOS + "/" + runtime.GOARCH,
		"samples": points, "traffic_samples": len(points), "memory_samples": memoryFrames,
		"connections_samples": connectionFrames, "quiet_log_samples": logFrames,
		"handshakes": counts, "max_active_connections": maxConnections,
		"interval_ns": intervals, "interval_min_ns": sorted[0], "interval_p50_ns": sorted[len(sorted)/2],
		"interval_max_ns": sorted[len(sorted)-1], "wall_duration_ns": time.Since(started).Nanoseconds(),
	}
	if path := os.Getenv("LAZYCLASH_WS_INTEGRATION_REPORT"); path != "" {
		data, err := json.MarshalIndent(report, "", "  ")
		if err != nil || os.WriteFile(path, data, 0600) != nil {
			t.Fatal("cannot write requested WebSocket integration report")
		}
	}
	t.Logf("real %s on %s/%s: %d traffic frames, cadence min/p50/max=%s/%s/%s, one handshake per source, quiet logs retained", version, runtime.GOOS, runtime.GOARCH, len(points), time.Duration(sorted[0]), time.Duration(sorted[len(sorted)/2]), time.Duration(sorted[len(sorted)-1]))
}
